import {surfaces,dimensions,fit,positions,migrate} from './castle-layout.mjs';
import {initSettings} from './castle-settings.mjs';
import roomImage from './castle-room-data.mjs';
import {loadAssets} from './display-api.mjs';
const $=s=>document.querySelector(s),room=$('#room'),picker=$('#picker'),bannerDialog=$('#bannerDialog');
$('#background').src=roomImage;
const key='edge-castle-room-v3';let state={pieces:surfaces.map(()=>[]),name:'',emblem:'',bannerColor:'#711d2c'},products=[],assets={},selected=0,editing=true;
try{let saved=JSON.parse(localStorage.getItem(key));if(!saved){const old=JSON.parse(localStorage.getItem('edge-castle-room-v2'));if(old?.pieces?.length===10)saved=migrate(old)}if(saved?.pieces?.length===9){state={...state,...saved,pieces:saved.pieces.map(a=>Array.isArray(a)?a.filter(x=>typeof x==='string'):[])};if(!/^#[0-9a-f]{6}$/i.test(state.bannerColor))state.bannerColor='#711d2c'}}catch{}
const selectedProducts=i=>state.pieces[i].map(id=>products.find(p=>p.id===id)).filter(Boolean);
const scale=()=>Number(room.dataset.mantel)||200;
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#status').textContent='Saved on this browser.'}catch{$('#status').textContent='Browser storage unavailable. Changes last for this visit.'}}
const bannerTint=document.createElementNS('http://www.w3.org/2000/svg','svg');bannerTint.setAttribute('viewBox','0 0 1024 1536');bannerTint.classList.add('banner-colour');bannerTint.innerHTML='<polygon points="870,438 974,417 974,932 917,1000 870,921"/>';room.append(bannerTint);
function renderBanner(){$('.crest').textContent=state.emblem;$('.banner-name').textContent=state.name;bannerTint.style.display=state.bannerColor==='#711d2c'?'none':'block';bannerTint.querySelector('polygon').setAttribute('fill',state.bannerColor)}
function render(){
 room.querySelectorAll('.placed-piece').forEach(el=>el.remove());
 surfaces.forEach((surface,i)=>{const items=selectedProducts(i),coords=positions(items,surface,scale()),button=room.querySelector('[data-slot="'+i+'"]');button.classList.toggle('filled',items.length>0);button.setAttribute('aria-label',surface[0]+': '+items.length+' pieces. Manage surface');
 items.forEach((product,j)=>{const at=coords[j],asset=assets[product.id];if(!asset)return;const im=new Image();im.className='placed-piece';im.src='/'+asset.src.replace(/^\//,'');im.alt=product.name;im.style.cssText=`left:${at.x/1024*100}%;top:${at.y/1536*100}%;height:${at.height/1536*100}%;width:${at.height*asset.width/asset.height/1024*100}%`;room.append(im)});
 });renderBanner();if(picker.open)list();
}
surfaces.forEach(([name,x,y,w],i)=>{const b=document.createElement('button');b.className='spot';b.dataset.slot=i;b.style.cssText=`left:${x/1024*100}%;top:${(y-90)/1536*100}%;width:${w/1024*100}%;height:${90/1536*100}%`;b.innerHTML='<span class="plus">+</span>';b.onclick=()=>{selected=i;$('#spotTitle').textContent=name;$('#search').value='';list();picker.showModal()};room.append(b)});
function list(){const items=selectedProducts(selected),d=dimensions(surfaces[selected],scale());$('#surfaceInfo').textContent=`Usable surface: ${Math.round(d.width-2*d.margin)} cm wide × ${Math.round(d.depth)} cm deep · ${Math.round(d.height)} cm height clearance. ${items.length} piece${items.length===1?'':'s'}.`;
 $('#placed').replaceChildren();state.pieces[selected].forEach((id,index)=>{const product=products.find(p=>p.id===id),row=document.createElement('div'),label=document.createElement('span'),remove=document.createElement('button');label.textContent=product?.name||'Unavailable catalogue piece';remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+label.textContent);remove.onclick=()=>{state.pieces[selected].splice(index,1);render();save();list()};row.append(label,remove);$('#placed').append(row)});
 const problems=[];let checked=[];for(const product of items){const reason=fit(checked,product,surfaces[selected],scale());if(reason)problems.push(product.name+': '+reason);checked.push(product)}$('#fitWarning').textContent=problems.length?'Saved pieces need rearranging: '+problems.join('; '):'';
 const q=$('#search').value.trim().toLowerCase(),matches=products.filter(p=>p.name.toLowerCase().includes(q));$('#choices').replaceChildren();for(const product of matches){const reason=fit(items,product,surfaces[selected],scale()),button=document.createElement('button'),im=new Image(),label=document.createElement('span');im.src='/'+assets[product.id].src.replace(/^\//,'');im.alt='';im.loading='lazy';label.textContent=product.name+` · ${product.h||'?'} H × ${product.w||'?'} W × ${product.d||'?'} D cm`+(reason?' — '+reason:' — Add');button.disabled=!!reason;button.append(im,label);button.onclick=()=>{if(fit(selectedProducts(selected),product,surfaces[selected],scale()))return;state.pieces[selected].push(product.id);render();save();list()};$('#choices').append(button)}if(!matches.length)$('#choices').textContent='No matching sculptures.';
}
$('#search').oninput=list;$('#remove').onclick=()=>{state.pieces[selected]=[];render();save();list()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function setEditing(value){editing=value;room.classList.toggle('editing',value);$('#edit').setAttribute('aria-pressed',String(value));document.querySelectorAll('.spot,#bannerHit,.room-hotspot').forEach(b=>b.tabIndex=value?0:-1)}
$('#edit').onclick=()=>{document.body.classList.remove('immersive');$('#view').setAttribute('aria-pressed','false');$('#view').textContent='View room';setEditing(!editing)};
$('#view').onclick=()=>{const on=document.body.classList.toggle('immersive');$('#view').setAttribute('aria-pressed',String(on));$('#view').textContent=on?'Exit view':'View room';setEditing(!on)};
function openBanner(){$('#house').value=state.name;$('#emblem').value=state.emblem;$('#bannerColor').value=state.bannerColor;bannerDialog.showModal()}$('#banner').onclick=openBanner;$('#bannerHit').onclick=openBanner;
$('#bannerForm').onsubmit=e=>{e.preventDefault();state.name=$('#house').value.trim();state.emblem=$('#emblem').value;state.bannerColor=$('#bannerColor').value;renderBanner();save();bannerDialog.close()};$('#bannerColor').oninput=()=>{state.bannerColor=$('#bannerColor').value;renderBanner();save()};$('#bannerOriginal').onclick=()=>{state.bannerColor='#711d2c';$('#bannerColor').value=state.bannerColor;renderBanner();save()};$('#blank').onclick=()=>{state.name='';state.emblem='';renderBanner();save();bannerDialog.close()};
$('#sample').disabled=true;$('#sample').onclick=()=>{state.pieces=surfaces.map(()=>[]);const groups=[['Gorilla Bust'],['Lion Bust'],['Highland Cow'],['Miniature Venus','Miniature Wolf','Miniature Sea Turtle'],['Baby Chimpanzee','Frog'],['Horse Bust'],['Sea Turtle','Chameleon'],['Venus Bust - Teal'],['Baby Orangutan']];groups.forEach((names,i)=>names.forEach(name=>{const product=products.find(p=>p.name===name)||products.find(p=>p.name.includes(name)&&(!p.name.startsWith('Miniature')||name.startsWith('Miniature')));if(product&&!fit(selectedProducts(i),product,surfaces[i],scale()))state.pieces[i].push(product.id)}));render();save()};
initSettings(room,render);
render();try{const loaded=await loadAssets();assets=loaded.assets;products=[...loaded.catalog.values()].filter(p=>assets[p.id]?.src).sort((a,b)=>a.name.localeCompare(b.name));render();$('#sample').disabled=!products.length;$('#status').textContent='Tap a display spot to begin.'}catch{$('#status').textContent='Could not load sculptures. Refresh to try again.'}
